{{define "leaderboard"}}
<label class="field">All-time</label>
{{if .Top}}
  {{range $i, $s := .Top}}
    <div class="player{{if and $.User (eq $s.PlayerID $.User.ID)}} me{{end}}">
      <span class="pixel rank">{{inc $i}}</span>
      <span class="dot" style="background:{{$s.Color}}"></span>
      <span class="name">{{$s.DisplayName}}</span>
      <span class="muted small games">{{$s.Wins}}W</span>
      <span class="score">{{$s.Score}}</span>
    </div>
  {{end}}
  {{if gt .MyRank 10}}
    <p class="muted small tight">You are #{{.MyRank}}. Keep playing.</p>
  {{end}}
{{else}}
  <p class="muted small tight">Nobody has finished a game yet. Be first.</p>
{{end}}
