<div class="topbar home-top">
  <span></span>
  <div class="row">
    <button type="button" class="ghost small" data-mute aria-label="Toggle sound">🔊</button>
    <div id="account">{{template "account" .}}</div>
  </div>
</div>

<section class="hero-big">
  <!-- One span per letter: each springs in on its own beat and boops on hover. -->
  <h1 class="wordmark" aria-label="deez.win">
    {{range $i, $ch := .Letters}}<span class="ltr" style="--i:{{$i}}">{{$ch}}</span>{{end}}
  </h1>
  <div class="sparkles" aria-hidden="true"></div>
  <p class="hero-line">2–4 players · dice decide · answers with receipts</p>
  <form method="get" action="/play" class="play-strip">
    <button class="primary big magnet"><span>Play</span></button>
  </form>
  <form method="post" action="/join" class="join-line" aria-label="Join with a code">
    <span class="muted small">Have a code?</span>
    <input type="text" class="code small-code" name="code" maxlength="4" placeholder="CODE"
           autocomplete="off" required pattern="[A-Za-z0-9]{4}" aria-label="Room code">
    <button class="ghost small">Join</button>
  </form>
</section>
<p class="footer home-foot">DATA BY CALA · IMAGES &amp; SOUND BY FAL.AI</p>
<script src="/home.js"></script>
{{end}}

{{define "account"}}
{{if and .User (not .User.IsAnon)}}
  <!-- <details> is the menu: no JS, closes on outside click via the summary. -->
  <details class="menu">
    <summary class="who"><span class="dot" style="background:{{.User.Color}}"></span>{{.User.DisplayName}}</summary>
    <div class="pop">
      <p class="small muted">{{or .User.Email .User.DisplayName}}</p>
      <form method="post" action="/logout"><button class="ghost small">Log out</button></form>
    </div>
  </details>
{{else}}
  <details class="menu">
    <summary class="who guest">{{with .User}}<span class="dot" style="background:{{.Color}}"></span>{{.DisplayName}} · {{end}}sign in</summary>
    <div class="pop">
      <p class="small muted">Keep your score on the board.</p>
      <form class="stack" hx-post="/login" hx-target="#account" hx-swap="innerHTML">
        <input type="email" name="email" placeholder="you@example.com" class="plain" required>
        <button class="primary">Email me a link</button>
      </form>
      <a class="btn google" href="{{.GoogleURL}}"><span class="g" aria-hidden="true">G</span> Continue with Google</a>
      {{with .LoginMsg}}<p class="small muted">{{.}}</p>{{end}}
    </div>
  </details>
{{end}}
{{end}}
{{define "body"}}
<div class="topbar">
  <a class="brand" href="/" aria-label="deez.win home"><i class="brand-die"></i>deez.win</a>
  <div class="row">
    <button type="button" class="ghost small" data-mute aria-label="Toggle sound">🔊</button>
    <div id="account">{{template "account" .}}</div>
  </div>
</div>

{{with .Error}}<div class="banner danger">{{.}}</div>{{end}}

<div class="column">
<section class="hero lobby-hero">
  <span class="eyebrow">Lobby</span>
  <h1 class="hero-title">Start a table or <em>join one</em>.</h1>
</section>

<div class="lobby-actions">
  <section class="card hero-card">
    <label class="field">Create a lobby</label>
    <form method="post" action="/rooms" class="stack">
      <div class="stepper" role="radiogroup" aria-label="Number of players">
        {{range $n := .PlayerCounts}}
          <label class="seg">
            <input type="radio" name="max_players" value="{{$n}}" {{if eq $n 3}}checked{{end}}>
            <span>{{$n}}</span>
          </label>
        {{end}}
      </div>
      <div class="row wrap">
        <button class="primary" name="public" value="0">Private lobby</button>
        <button class="ghost" name="public" value="1">Public lobby</button>
      </div>
    </form>
  </section>

  <section class="card">
    <label class="field">Join with a code</label>
    <form method="post" action="/join" class="stack">
      <input type="text" class="code" name="code" maxlength="4" placeholder="CODE"
             autocomplete="off" required pattern="[A-Za-z0-9]{4}" aria-label="Room code">
      <button>Join lobby</button>
    </form>
  </section>
</div>

<div class="grid2 lobby-grid">
  <!-- Polled separately so a lobby appearing elsewhere shows up here without
       touching the rest of the page. -->
  <div class="card" hx-get="/lobbies" hx-trigger="every 5s" hx-target="this" hx-swap="innerMorph">
    {{template "lobbies" .}}
  </div>
  <div class="card" id="leaderboard" hx-get="/leaderboard" hx-trigger="every 10s" hx-target="this" hx-swap="innerMorph">
    {{template "leaderboard" .}}
  </div>
</div>

</div>

<p class="footer">DATA BY CALA · IMAGES &amp; SOUND BY FAL.AI</p>
{{end}}

{{define "lobbies"}}
<label class="field">Public lobbies</label>
{{if .Lobbies}}
  {{range .Lobbies}}
    <div class="lobby-item">
      <span class="pixel small">{{.Code}}</span>
      <span class="muted small">{{.Players}}/{{.MaxPlayers}} players</span>
      <form method="post" action="/join"><input type="hidden" name="code" value="{{.Code}}"><button>Join</button></form>
    </div>
  {{end}}
{{else}}
  <p class="muted small tight">Nobody is waiting right now. Make a public lobby and it shows up here.</p>
{{end}}
{{end}}

{{define "account"}}
{{if and .User (not .User.IsAnon)}}
  <!-- <details> is the menu: no JS, closes on outside click via the summary. -->
  <details class="menu">
    <summary class="who"><span class="dot" style="background:{{.User.Color}}"></span>{{.User.DisplayName}}</summary>
    <div class="pop">
      <p class="small muted">{{or .User.Email .User.DisplayName}}</p>
      <form method="post" action="/logout"><button class="ghost small">Log out</button></form>
    </div>
  </details>
{{else}}
  <details class="menu">
    <summary class="who guest">{{with .User}}<span class="dot" style="background:{{.Color}}"></span>{{.DisplayName}} · {{end}}sign in</summary>
    <div class="pop">
      <p class="small muted">Keep your score on the board.</p>
      <form class="stack" hx-post="/login" hx-target="#account" hx-swap="innerHTML">
        <input type="email" name="email" placeholder="you@example.com" class="plain" required>
        <button class="primary">Email me a link</button>
      </form>
      <a class="btn google" href="{{.GoogleURL}}"><span class="g" aria-hidden="true">G</span> Continue with Google</a>
      {{with .LoginMsg}}<p class="small muted">{{.}}</p>{{end}}
    </div>
  </details>
{{end}}
{{end}}

{{define "leaderboard"}}
<label class="field">All-time</label>
{{if .Top}}
  {{range $i, $s := .Top}}
    <div class="player{{if and $.User (eq $s.PlayerID $.User.ID)}} me{{end}}">
      <span class="pixel rank">{{inc $i}}</span>
      <span class="dot" style="background:{{$s.Color}}"></span>
      <span class="name">{{$s.DisplayName}}</span>
      <span class="muted small games">{{$s.Wins}}W</span>
      <span class="score">{{$s.Score}}</span>
    </div>
  {{end}}
  {{if gt .MyRank 10}}
    <p class="muted small tight">You are #{{.MyRank}}. Keep playing.</p>
  {{end}}
{{else}}
  <p class="muted small tight">Nobody has finished a game yet. Be first.</p>
{{end}}
{{end}}
