package main

import (
	"context"
	"errors"
	"net/http"
	"sync"
)

// Dev auth is a local stand-in for D3BIT, enabled only by -dev-auth.
//
// It exists because D3BIT's /auth/anon is not always reachable (it is 500ing
// on production as of this writing) and a hackathon team should not be blocked
// on someone else's outage. It is off by default and must never be enabled on
// anything public: it hands out a session to whoever asks, with no verification.
type DevAuth struct {
	mu       sync.Mutex
	sessions map[string]*D3bitUser
	seq      int
}

var devNames = []string{"Pixel", "Comet", "Marble", "Falcon", "Tundra", "Nimbus", "Cobalt", "Sorrel"}
var devColors = []string{"#7cf5c8", "#ffd166", "#ff6b8a", "#7c9cff", "#c792ea", "#f78c6c"}

func NewDevAuth() *DevAuth {
	return &DevAuth{sessions: make(map[string]*D3bitUser)}
}

func (d *DevAuth) Routes(mux *http.ServeMux) {
	mux.HandleFunc("GET /d3bit/auth/me", d.me)
	mux.HandleFunc("POST /d3bit/auth/anon", d.anon)
	mux.HandleFunc("POST /d3bit/auth/logout", d.logout)

	// Login paths exist so the UI behaves identically; they are inert here.
	notSupported := func(w http.ResponseWriter, r *http.Request) {
		httpError(w, http.StatusNotImplemented, "dev_auth",
			"Dev auth has no email or Google sign-in. Point -d3bit at a real D3BIT instance.")
	}
	mux.HandleFunc("POST /d3bit/auth/login", notSupported)
	mux.HandleFunc("POST /d3bit/auth/claim", notSupported)
	mux.HandleFunc("PATCH /d3bit/auth/me", notSupported)
}

func (d *DevAuth) anon(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, map[string]any{"data": map[string]any{"user": d.mint(w)}})
}

func (d *DevAuth) mint(w http.ResponseWriter) *D3bitUser {
	d.mu.Lock()
	d.seq++
	u := &D3bitUser{
		ID:          "dev_" + newCode() + newCode(),
		IsAnon:      true,
		DisplayName: devNames[d.seq%len(devNames)],
		Color:       devColors[d.seq%len(devColors)],
	}
	token := "devsess_" + newCode() + newCode() + newCode()
	d.sessions[token] = u
	d.mu.Unlock()

	http.SetCookie(w, &http.Cookie{
		Name: "d3_session", Value: token, Path: "/",
		HttpOnly: true, MaxAge: 86400, SameSite: http.SameSiteLaxMode,
	})
	return u
}

// Bootstrap mints a local session, matching the real Auth's contract.
func (d *DevAuth) Bootstrap(w http.ResponseWriter, r *http.Request) *D3bitUser {
	return d.mint(w)
}

// SendMagicLink is inert in dev mode; there is no mail path.
func (d *DevAuth) SendMagicLink(ctx context.Context, email, redirect string) error {
	return errors.New("Dev auth has no email sign-in. Point -d3bit at a real D3BIT instance.")
}

func (d *DevAuth) me(w http.ResponseWriter, r *http.Request) {
	u := d.User(r)
	if u == nil {
		httpError(w, http.StatusUnauthorized, "unauthenticated", "No session.")
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"data": u})
}

func (d *DevAuth) logout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie("d3_session"); err == nil {
		d.mu.Lock()
		delete(d.sessions, c.Value)
		d.mu.Unlock()
	}
	http.SetCookie(w, &http.Cookie{Name: "d3_session", Value: "", Path: "/", MaxAge: -1})
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

func (d *DevAuth) User(r *http.Request) *D3bitUser {
	c, err := r.Cookie("d3_session")
	if err != nil || c.Value == "" {
		return nil
	}
	d.mu.Lock()
	defer d.mu.Unlock()
	return d.sessions[c.Value]
}

// Logout clears the local session.
func (d *DevAuth) Logout(w http.ResponseWriter, r *http.Request) {
	d.logout(w, r)
}
{{define "body"}}
<div class="topbar">
  <div>
    <a class="brand small-brand" href="/"><span class="brand-die" aria-hidden="true"></span>DEEZ.WIN</a>
    <div class="room-head">
      <span class="pixel room-code">{{.Room.Code}}</span>
      <span class="muted small">{{len .Room.Players}}/{{.Room.MaxPlayer}} players</span>
      {{if not .CalaEnabled}}<span class="tag warn">offline data</span>{{else}}<span class="tag live">live graph</span>{{end}}
    </div>
  </div>
  <div class="row">
    <button type="button" class="ghost small" data-mute aria-label="Toggle sound">🔊</button>
    {{with .User}}<span class="who static"><span class="dot" style="background:{{.Color}}"></span>{{.DisplayName}}</span>{{end}}
    <a class="btn ghost small" href="/">Leave</a>
  </div>
</div>

<div class="grid">
  <!--
    One polled region for the whole game.

    hx-target:inherited is the htmx 4 way to say "everything inside me swaps
    here". In 2.x this was implicit; now it is opt-in, which means the buttons
    below need no target of their own and a stray hx-get can't hijack the page.

    innerMorph rather than innerHTML: morphing keeps the dice mid-animation and
    keeps focus in the topic input while the poll runs underneath.
  -->
  <div id="panel" class="stack"
       hx-get="/rooms/{{.Room.Code}}/panel"
       hx-trigger="every 1s"
       hx-target="this"
       hx-swap="innerMorph"
       hx-target:inherited="#panel"
       hx-swap:inherited="innerMorph">
    {{template "panel" .}}
  </div>

  <div class="stack">
    <div id="roster" class="card">{{template "roster" .}}</div>
  </div>
</div>

<p class="footer">DATA BY CALA · SOUND BY FAL.AI · NO MODEL DECIDES WHAT IS TRUE</p>
{{end}}

{{define "roster"}}
<label class="field">Players</label>
{{range .Room.Players}}
  <div class="player">
    <span class="dot" style="background:{{.Color}}"></span>
    <span class="name">{{.DisplayName}}{{if eq .ID $.Me}} <span class="muted small">(you)</span>{{end}}</span>
    {{if eq .ID $.Picking}}<span class="tag live">picking</span>{{end}}
    {{if .IsHost}}<span class="tag">host</span>{{end}}
    <span class="score">{{.Score}}</span>
  </div>
{{end}}
{{if .Room.Loads}}
  <div class="topic-strip">
    <label class="field">Loading</label>
    <ol class="pipe">
      {{range .Room.Loads}}
        <li class="step {{.State}}">
          <span class="node" aria-hidden="true"></span>
          <span class="step-body">
            <span class="step-label">{{.Label}}<span class="muted small step-time">{{.Elapsed}}</span></span>
            {{with .Detail}}<span class="small muted">{{.}}</span>{{end}}
            {{if gt .Total 0}}<span class="step-bar"><i style="width:{{.Pct}}%"></i></span>{{end}}
          </span>
        </li>
      {{end}}
    </ol>
  </div>
{{end}}
{{with .Room.Topic}}
  <div class="topic-strip">
    <label class="field">Topic</label>
    {{with $.Room.Cover}}<img class="cover" src="{{.}}" alt="" width="512" height="512">{{end}}
    <div class="pixel topic-name">{{.}}</div>
    {{if $.Entities}}
      <div class="chips">{{range $.Entities}}<span class="chip">{{.}}</span>{{end}}</div>
    {{end}}
  </div>
{{end}}
{{end}}
{{define "panel"}}
<!-- The roster rides along out of band so one poll updates scores too. Only
     on polls: on the full page it would be a second #roster and the OOB swap
     would land in the wrong one. -->
{{if not .FullPage}}<div id="roster" hx-swap-oob="innerMorph">{{template "roster" .}}</div>{{end}}

{{if .Room.Error}}<div class="banner danger">{{.Room.Error}}</div>{{end}}
{{with .Flash}}<div class="banner danger">{{.}}</div>{{end}}
{{with .Room.Notice}}<div class="banner">{{.}}</div>{{end}}

{{if eq .Room.Phase "lobby"}}
  <div class="card stack phase" data-sfx-phase="lobby">
    <span class="eyebrow">Lobby</span>
    <h2 class="pixel h2">Waiting for players</h2>
    <p class="muted">Share the code. The game starts on its own when the room fills.</p>
    <div class="code-plate pixel">{{.Room.Code}}</div>
    <div class="progress"><i style="width:{{.FillPct}}%"></i></div>
  </div>

{{else if eq .Room.Phase "rolling"}}
  <div class="card phase" data-sfx-phase="rolling">
    <span class="eyebrow">Roll</span>
    <h2 class="pixel h2">{{if .RollWinner}}{{.RollWinner}} picks the topic{{else}}Highest die picks the topic{{end}}</h2>
    <div class="dice-wrap">
      {{range .Room.Players}}
        <div>
          {{template "die" .}}
          <div class="die-label">{{.DisplayName}}</div>
        </div>
      {{end}}
    </div>
    {{if not .IHaveRolled}}
      <!-- The dice are theatre, not a decision: fire once, after a beat, so the
           animation is seen. `load delay:` means no JS is needed for it. -->
      <div hx-post="/rooms/{{.Room.Code}}/roll" hx-trigger="load delay:2400ms"></div>
    {{end}}
    <p class="muted small center">{{if .RollWinner}}Locking it in…{{else}}Rolling…{{end}}</p>
  </div>

{{else if eq .Room.Phase "topic"}}
  {{if .IsTopicPicker}}
    <div class="card stack phase" data-sfx-phase="topic">
      <span class="eyebrow">Your pick</span>
      <h2 class="pixel h2">You won the roll</h2>
      <p class="muted">Name a set of things. The graph resolves it to real entities and the others each claim an axis.</p>
      <form hx-post="/rooms/{{.Room.Code}}/topic" class="stack">
        <input type="text" name="topic" class="plain topic-input" placeholder="{{index .Suggestions 0}}…" autocomplete="off" autofocus required>
        <div class="row wrap">
          {{range .Suggestions}}
            <!-- Own request, not the form's submitter: htmx 4 does not send
                 the clicked button's name/value with a form post. -->
            <button type="button" class="ghost small"
                    hx-post="/rooms/{{$.Room.Code}}/topic"
                    hx-vals='{"topic":"{{.}}"}'>{{.}}</button>
          {{end}}
        </div>
        <button class="primary big">Lock it in</button>
      </form>
    </div>
  {{else}}
    <div class="card phase">
      <span class="eyebrow">Topic</span>
      <h2 class="pixel h2">{{.PickerName}} is choosing</h2>
      <p class="muted">They won the roll. You claim an axis next.</p>
      <div class="progress indeterminate"><i></i></div>
    </div>
  {{end}}

{{else if eq .Room.Phase "subtopics"}}
  <div class="card stack phase" data-sfx-phase="subtopics">
    <span class="eyebrow">Claim an axis</span>
    <h2 class="pixel h2">{{if .IsMyPick}}Your pick{{else}}{{.PickerName}} is picking{{end}}</h2>
    <p class="muted">The top {{len .SubTopics}} things the graph actually holds for <strong>{{.Room.Topic}}</strong>.
      Questions come from these. Yours pays half.</p>
    <div class="axes">
      {{range .SubTopics}}
        <button class="axis{{if .ClaimedBy}} claimed{{end}}"
                hx-post="/rooms/{{$.Room.Code}}/subtopic"
                hx-vals='{"key":"{{.Key}}"}'
                {{if or (not $.IsMyPick) .ClaimedBy}}disabled{{end}}>
          <span class="axis-glyph kind-{{.Kind}}" aria-hidden="true"></span>
          <span class="axis-body">
            <strong>{{.Label}}</strong>
            <span class="small muted">{{.Kind}}{{with .OwnerName}} · {{.}}{{end}}</span>
          </span>
        </button>
      {{end}}
    </div>
  </div>

{{else if eq .Room.Phase "building"}}
  <div class="card phase" data-sfx-phase="building">
    <span class="eyebrow">Building</span>
    <h2 class="pixel h2">Reading the graph</h2>
    <p class="muted">{{or .Room.Status "Working…"}}{{if not .Entities}} <span class="small">This can take a minute the first time a topic is asked.</span>{{end}}</p>
    {{with .Room.Cover}}<img class="cover big-cover" src="{{.}}" alt="" width="512" height="512">{{end}}
    {{if .Entities}}
      <div class="chips ticking">{{range $i, $e := .Entities}}<span class="chip" style="--i:{{$i}}">{{$e}}</span>{{end}}</div>
    {{end}}
    <div class="progress indeterminate"><i></i></div>
