{{else if eq .Room.Phase "quiz"}}
  {{with .Question}}
    <div class="card phase quiz" data-sfx-phase="quiz" data-question="{{.Index}}"
         {{if .Answered}}data-sfx="{{if .WasCorrect}}correct{{else}}wrong{{end}}"{{end}}>
      <div class="row spread small muted">
        <span class="pixel">Q{{.Number}}<span class="dim">/{{$.Room.QuestionCount}}</span></span>
        {{if .Seeded}}<span class="tag warn">your axis · half points</span>{{end}}
      </div>
      <!-- Keyed by index so the morph replaces it and the bonus drain restarts. -->
      <div class="bonus" id="bonus-{{.Index}}" title="speed bonus"><i class="{{if .Answered}}stopped{{end}}"></i></div>
      <p class="prompt">{{.Prompt}}</p>
      <div class="choices">
        {{range .Choices}}
          <button class="choice {{.Class}}"
                  data-key="{{.Index}}"
                  hx-post="/rooms/{{$.Room.Code}}/answer"
                  hx-vals='{"index":"{{$.Question.Index}}","choice":"{{.Index}}"}'
                  {{if $.Question.Answered}}disabled{{end}}>
            <span class="key">{{.Letter}}</span> {{.Text}}
